Q: Can I iterate over/get an iterable over multiple promises by order of their settlement? A: <p>I guess that the short answer is no, but here is what you can do:</p>
<p>Here is an example of how you get a function called on each promise and on all promises (it is not clear to me if you need both). For getting a done promise on each you append <code>.then(onedone)</code> on the function that returns the promise. And then use <code>Promise.all(promises).then(alldone);</code> if you need something called when they are all done. The way you will get the returned values for each promise when all are done is to add a return statement in the <code>onedone()</code> callback function.</p>
<p>If you need some kind of status on the overall &quot;process&quot; of resolving things you can add the resolved promises to an array then each are done.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let myarr = [0, 500, 1000, 1500, 2000];
let donearr = [];

let promises = myarr.map(time =&gt; myAsyncFn(time).then(onedone).then(status));

Promise.all(promises).then(alldone);

function myAsyncFn(time) {
  return new Promise(resolve =&gt; {
    setTimeout(resolve, time, `time: ${time}`);
  });
}

function onedone(one) {
  console.log(one);
  donearr.push(one);
  return one; // return if you need all values in the alldone()
}

function alldone(all) {
  console.log('all done: ', JSON.stringify(all));
}

function status(one){
  document.getElementById('meter01').value = donearr.length / myarr.length;
  return one;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;meter id="meter01" value="0" min="0" max="1"&gt;&lt;/meter&gt;</code></pre>
</div>
</div>
</p>

